  assert.ok(probes.length>=2,'At least two front sources are visible in the overlapping cluster');for(const p of probes){assert.ok(p.under.every(z=>z<p.z));await page.mouse.click(p.x,p.y);assert.equal(await page.$eval('[data-motion-layer="'+p.id+'"]',n=>n.getAttribute('aria-pressed')),'true');}
