  // Reordering moves the source and its authored crop together.
  await change('[data-motion-stream-order]','2');const ordered=await pose(0);assert.equal(ordered[1].id,start[0].id);assert.equal(await page.$eval('[data-motion-image-focus="y"]',n=>n.value),'100');await change('[data-motion-stream-order]','1');await change('[data-motion-config="source"]','scroll');await change('[data-motion-stream="turns"]','3');await change('[data-motion-stream="start"]','20');await change('[data-motion-stream="end"]','80');await change('[data-motion-stream="scrollLength"]','420');assert.equal((await pose(.5))[0].phase,'1.500000');assert.deepEqual(geometry(await pose(.1)),geometry(await pose(.9)));assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);assert.equal(await page.evaluate(()=>localStorage.getItem(STORE_KEY)),before.stored);
  await page.click('[data-motion-library-tab="library"]');await page.$eval('[data-motion-library-name]',(n,template)=>n.value='Mi '+template,template);await page.click('[data-motion-library-save]');const saved=await page.evaluate(()=>project.nwMotionLibrary.at(-1));assert.equal(saved.config.stream.kind,template);assert.equal(saved.assets.length,8);await page.click('[data-motion-saved="'+saved.id+'"]');await ready();const copied=await pose(.35);assert.ok(copied.every(n=>!start.some(o=>o.id===n.id)));await page.click('[data-motion-insert-group]');const inserted=await page.evaluate(()=>{const g=sec().elements.find(e=>e.nwMotionInstance);return{gid:g.id,outside:sec().elements[0],enabled:sec().sdEnabled,length:sec().sdLength};});assert.deepEqual(inserted.outside,before.outside);assert.equal(inserted.enabled,true);assert.equal(inserted.length,420);await page.waitForFunction(id=>document.querySelector('#preview')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[id]&&document.querySelector('#preview').contentDocument.querySelector('.nw-photo-card'),{},inserted.gid);await actualScroll('#preview',inserted.gid);await exported(inserted.gid);assert.deepEqual((await pose(.35,'#photo-export',inserted.gid)).map(n=>n.src),copied.map(n=>n.src));await page.$eval('#photo-export',(f,id)=>f.contentWindow.__NAG_SCROLL_DIRECTOR[id].live(),inserted.gid);await actualScroll('#photo-export',inserted.gid);await page.evaluate(()=>document.querySelector('#photo-export').remove());
